<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/includes/bootstrap.php';
require_permission('vendors.view');
if(is_post()){require_permission('vendors.manage');verify_csrf();try{$id=(int)input('vendor_id');$status=strtoupper((string)input('status'));if(!in_array($status,['DRAFT','PENDING_KYC','PENDING_BANK','PENDING_APPROVAL','VERIFIED','ACTIVE','REJECTED','SUSPENDED','CLOSED','BLOCKED','INACTIVE'],true))throw new InvalidArgumentException('Invalid status.');$pdo=db();$pdo->prepare('UPDATE vendors SET status=? WHERE id=?')->execute([$status,$id]);audit_log((int)admin()['id'],'VENDOR_STATUS_CHANGED','vendors',(string)$id,['status'=>$status]);flash('success','Vendor status updated.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/vendors/index.php');}
$vendors=db()->query('SELECT v.*,(SELECT COUNT(*) FROM vendor_users WHERE vendor_id=v.id) users,(SELECT COUNT(*) FROM gift_redemptions WHERE vendor_id=v.id) redemptions FROM vendors v ORDER BY v.id DESC')->fetchAll();$pageTitle='Vendor directory';$pageSubtitle='Merchant profiles, verification status and redemptions';require APP_ROOT.'/includes/header.php';
?><section class="panel"><div class="panel-head"><div><h2>Vendor directory &amp; profiles</h2><p class="help">Use Vendor Onboarding for new registrations. Open a vendor for the complete 360° profile.</p></div><?php if(can('vendors.manage')):?><a class="btn" href="<?=e(app_url('/admin/vendors/onboarding.php'))?>">Open Vendor Onboarding</a><?php endif?></div><div class="table-wrap"><table><thead><tr><th>Code</th><th>Vendor / shop</th><th>Contact</th><th>Users</th><th>Redemptions</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($vendors as $v):?><tr><td><?=e($v['vendor_code'])?></td><td><?=e($v['name'])?><br><small><?=e($v['shop_name'])?></small></td><td><?=e($v['email']??'—')?><br><?=e($v['mobile']??'—')?></td><td><?=e($v['users'])?></td><td><?=e($v['redemptions'])?></td><td><span class="badge <?=strtolower(e($v['status']))?>"><?=e($v['status'])?></span></td><td><div class="actions"><a class="btn small secondary" href="<?=e(app_url('/admin/vendors/profile.php?id='.$v['id']))?>">View profile</a><?php if(can('vendors.manage')):?><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="vendor_id" value="<?=e($v['id'])?>"><select name="status"><?php foreach(['DRAFT','PENDING_KYC','PENDING_BANK','PENDING_APPROVAL','VERIFIED','ACTIVE','REJECTED','SUSPENDED','CLOSED'] as $st):?><option <?=$v['status']===$st?'selected':''?>><?=e($st)?></option><?php endforeach?></select><button class="btn small">Save</button></form><?php endif?></div></td></tr><?php endforeach?></tbody></table><?php if(!$vendors):?><div class="empty">No vendors configured.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
